package com.hbm.satellite.control;
import com.mojang.serialization.MapCodec;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Source ordinary full cube, both top/bottom programmer texture, exact independent inventory spill distribution. */
public final class SatelliteLinkerBlock extends BaseEntityBlock {
 private final java.util.Random dropRandom=new java.util.Random();public SatelliteLinkerBlock(){super(Properties.of().strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops());}@Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}@Override protected RenderShape getRenderShape(BlockState state){return RenderShape.MODEL;}@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new SatelliteLinkerBlockEntity(pos,state);}@Override public <T extends BlockEntity>BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return level.isClientSide?null:createTickerHelper(type,SatelliteControlContent.ENTITY.get(),(world,pos,current,linker)->linker.tick());}
 @Override protected InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,BlockHitResult hit){if(player.isShiftKeyDown())return InteractionResult.PASS;if(!level.isClientSide&&level.getBlockEntity(pos) instanceof SatelliteLinkerBlockEntity machine)((net.minecraft.server.level.ServerPlayer)player).openMenu(machine,pos);return InteractionResult.sidedSuccess(level.isClientSide);}
 @Override public void setPlacedBy(Level level,BlockPos pos,BlockState state,LivingEntity placer,ItemStack stack){super.setPlacedBy(level,pos,state,placer,stack);var name=stack.get(net.minecraft.core.component.DataComponents.CUSTOM_NAME);if(name!=null&&level.getBlockEntity(pos) instanceof SatelliteLinkerBlockEntity machine)machine.setCustomName(name);}
 @Override protected void onRemove(BlockState state,Level level,BlockPos pos,BlockState replacement,boolean moving){if(state.getBlock()!=replacement.getBlock()&&level.getBlockEntity(pos) instanceof SatelliteLinkerBlockEntity machine){if(!level.isClientSide)for(int i=0;i<3;i++){var stack=machine.getItem(i);if(stack.isEmpty())continue;float x=dropRandom.nextFloat()*.8F+.1F,y=dropRandom.nextFloat()*.8F+.1F,z=dropRandom.nextFloat()*.8F+.1F;while(!stack.isEmpty()){int count=Math.min(stack.getCount(),dropRandom.nextInt(21)+10);var drop=new ItemEntity(level,pos.getX()+x,pos.getY()+y,pos.getZ()+z,stack.split(count));drop.setDeltaMovement((float)dropRandom.nextGaussian()*.05F,(float)dropRandom.nextGaussian()*.05F+.2F,(float)dropRandom.nextGaussian()*.05F);level.addFreshEntity(drop);}}level.updateNeighbourForOutputSignal(pos,this);}super.onRemove(state,level,pos,replacement,moving);}
}
